create or replace function private.sales_commercial_expand_v610(p_tenant_id uuid,p_order_type text,p_items jsonb,p_discount_type text default 'none',p_discount_value numeric default 0,p_charge_selections jsonb default '[]'::jsonb) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ declare v_order_type text:=lower(trim(coalesce(p_order_type,'sale')));v_discount_type text:=lower(trim(coalesce(p_discount_type,'none')));v_discount_value numeric:=greatest(coalesce(p_discount_value,0),0);v_items jsonb:='[]'::jsonb;v_charge_items jsonb:='[]'::jsonb;v_breakdown jsonb:='[]'::jsonb;v_line jsonb;v_count integer;v_index integer:=0;v_qty numeric;v_price numeric;v_existing_discount numeric;v_line_net numeric;v_base_net numeric:=0;v_doc_discount numeric:=0;v_alloc numeric:=0;v_remaining numeric:=0;v_charge_total numeric:=0;v_subtotal numeric:=0;v_discount_total numeric:=0;v_tax numeric:=0;v_taxable numeric:=0; begin if v_order_type='counter' then v_order_type:='sale';end if;if v_order_type not in('sale','dine_in','takeaway','delivery') then raise exception 'Invalid commercial order type %',v_order_type;end if;if v_discount_type not in('none','fixed','percent') then raise exception 'Invalid document discount type %',v_discount_type;end if;if v_discount_type='percent' and v_discount_value>100 then raise exception 'Document discount percent cannot exceed 100';end if;if jsonb_typeof(coalesce(p_items,'[]'::jsonb))<>'array' or jsonb_array_length(coalesce(p_items,'[]'::jsonb))=0 then raise exception 'Commercial quote requires at least one item';end if;if jsonb_typeof(coalesce(p_charge_selections,'[]'::jsonb))<>'array' then raise exception 'Commercial charge selections must be an array';end if;v_count:=jsonb_array_length(p_items);for v_line in select value from jsonb_array_elements(p_items) loop v_qty:=greatest(coalesce(nullif(v_line->>'quantity','')::numeric,0),0);v_price:=greatest(coalesce(nullif(v_line->>'unit_price','')::numeric,0),0);v_existing_discount:=greatest(coalesce(nullif(v_line->>'discount_amount','')::numeric,0),0);v_line_net:=greatest(v_qty*v_price-v_existing_discount,0);v_base_net:=v_base_net+v_line_net;end loop;if v_discount_type='fixed' then v_doc_discount:=least(v_discount_value,v_base_net);elsif v_discount_type='percent' then v_doc_discount:=round(v_base_net*v_discount_value/100,6);else v_doc_discount:=0;end if;v_remaining:=v_doc_discount;for v_line in select value from jsonb_array_elements(p_items) loop v_index:=v_index+1;v_qty:=greatest(coalesce(nullif(v_line->>'quantity','')::numeric,0),0);v_price:=greatest(coalesce(nullif(v_line->>'unit_price','')::numeric,0),0);v_existing_discount:=greatest(coalesce(nullif(v_line->>'discount_amount','')::numeric,0),0);v_line_net:=greatest(v_qty*v_price-v_existing_discount,0);if v_remaining>0 and v_line_net>0 and v_base_net>0 then if v_index=v_count then v_alloc:=least(v_remaining,v_line_net);else v_alloc:=least(round(v_doc_discount*v_line_net/v_base_net,6),v_remaining,v_line_net);end if;else v_alloc:=0;end if;v_items:=v_items||jsonb_build_array(v_line||jsonb_build_object('discount_amount',round(v_existing_discount+v_alloc,6)));v_remaining:=greatest(v_remaining-v_alloc,0);end loop;with input_lines as(select nullif(x.value->>'variant_id','')::uuid variant_id,greatest(coalesce(nullif(x.value->>'quantity','')::numeric,0),0) quantity from jsonb_array_elements(p_items)x(value)),manual_contrib as(select nullif(s.value->>'charge_id','')::uuid charge_id,greatest(coalesce(nullif(s.value->>'quantity','')::numeric,1),0) quantity,'manual'::text source from jsonb_array_elements(coalesce(p_charge_selections,'[]'::jsonb))s(value) where jsonb_typeof(s.value)='object' and nullif(s.value->>'charge_id','') is not null),auto_contrib as(select c.id,c.default_quantity,'order_default'::text from public.sales_charge_catalog_v610 c where c.tenant_id=p_tenant_id and c.active and((v_order_type='dine_in' and c.auto_apply_dine_in)or(v_order_type='takeaway' and c.auto_apply_takeaway)or(v_order_type='delivery' and c.auto_apply_delivery))),rule_contrib as(select r.charge_catalog_id,sum(case when r.quantity_mode='per_unit' then i.quantity*r.quantity_value when r.quantity_mode='per_line' then r.quantity_value else 0 end)+max(case when r.quantity_mode='fixed' then r.quantity_value else 0 end),'product_rule'::text from input_lines i join public.product_charge_rules_v610 r on r.tenant_id=p_tenant_id and r.product_variant_id=i.variant_id and r.active and r.order_type in('all',v_order_type) group by r.charge_catalog_id),combined as(select * from manual_contrib union all select * from auto_contrib union all select * from rule_contrib),agg as(select charge_id,sum(quantity) quantity,jsonb_agg(distinct source) sources from combined where charge_id is not null and quantity>0 group by charge_id),rows as(select c.id charge_id,c.code,c.name,c.charge_kind,c.service_variant_id,a.quantity,a.sources,pv.selling_price unit_price,p.tax_rate,p.tax_code from agg a join public.sales_charge_catalog_v610 c on c.id=a.charge_id and c.tenant_id=p_tenant_id and c.active join public.product_variants pv on pv.id=c.service_variant_id and pv.tenant_id=c.tenant_id and pv.status='active' join public.products p on p.id=pv.product_id and p.tenant_id=pv.tenant_id and p.status='active' and p.item_type='service') select coalesce(jsonb_agg(jsonb_build_object('variant_id',service_variant_id,'quantity',quantity,'unit_price',unit_price,'discount_amount',0,'tax_rate',tax_rate,'commercial_charge_id',charge_id,'commercial_charge_kind',charge_kind,'commercial_charge_code',code) order by name,code),'[]'::jsonb),coalesce(jsonb_agg(jsonb_build_object('charge_id',charge_id,'code',code,'name',name,'kind',charge_kind,'variant_id',service_variant_id,'quantity',quantity,'unit_price',unit_price,'tax_rate',tax_rate,'tax_code',tax_code,'taxable_value',round(quantity*unit_price,2),'tax_amount',round(quantity*unit_price*tax_rate/100,2),'line_total',round(quantity*unit_price*(1+tax_rate/100),2),'sources',sources) order by name,code),'[]'::jsonb),coalesce(sum(quantity*unit_price),0) into v_charge_items,v_breakdown,v_charge_total from rows;v_items:=v_items||v_charge_items;select coalesce(sum(greatest(coalesce(nullif(x.value->>'quantity','')::numeric,0),0)*greatest(coalesce(nullif(x.value->>'unit_price','')::numeric,0),0)),0),coalesce(sum(greatest(coalesce(nullif(x.value->>'discount_amount','')::numeric,0),0)),0),coalesce(sum(greatest(greatest(coalesce(nullif(x.value->>'quantity','')::numeric,0),0)*greatest(coalesce(nullif(x.value->>'unit_price','')::numeric,0),0)-greatest(coalesce(nullif(x.value->>'discount_amount','')::numeric,0),0),0)),0),coalesce(sum(greatest(greatest(coalesce(nullif(x.value->>'quantity','')::numeric,0),0)*greatest(coalesce(nullif(x.value->>'unit_price','')::numeric,0),0)-greatest(coalesce(nullif(x.value->>'discount_amount','')::numeric,0),0),0)*greatest(coalesce(nullif(x.value->>'tax_rate','')::numeric,0),0)/100),0) into v_subtotal,v_discount_total,v_taxable,v_tax from jsonb_array_elements(v_items)x(value);return jsonb_build_object('order_type',v_order_type,'discount_type',v_discount_type,'discount_value',v_discount_value,'document_discount_total',round(v_doc_discount,2),'classified_charge_total',round(v_charge_total,2),'charge_breakdown',v_breakdown,'items',v_items,'totals',jsonb_build_object('subtotal',round(v_subtotal,2),'discount',round(v_discount_total,2),'taxable',round(v_taxable,2),'tax',round(v_tax,2),'before_round_off',round(v_taxable+v_tax,2),'automatic_round_off',round(round(v_taxable+v_tax,0)-(v_taxable+v_tax),2),'grand_total',round(v_taxable+v_tax+round(round(v_taxable+v_tax,0)-(v_taxable+v_tax),2),2)));end;$$;;
